class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private boolean check(TreeNode node, int targetSum, int current) {
    if (node == null) {
      return false;
    }
    current += node.val;
    if (node.left == null && node.right == null) {
      return current == targetSum;
    }
    return check(node.left, targetSum, current) || check(node.right, targetSum, current);
  }

  public boolean hasPathSum(TreeNode root, int targetSum) {
    return check(root, targetSum, 0);
  }
}

class Solution:
    def hasPathSum(self, root: Optional[TreeNode], targetSum: int) -> bool:
        if root is None:
            return False
        targetSum -= root.val
        if root.left is None and root.right is None:
            return targetSum == 0
        return self.hasPathSum(root.left, targetSum) or self.hasPathSum(root.right, targetSum)

impl Solution {
  pub fn has_path_sum(root: Option<Box<TreeNode>>, target_sum: i32) -> bool {
    fn check(node: &Option<Box<TreeNode>>, current: i32, target: i32) -> bool {
      match node {
        None => false,
        Some(n) => {
          let sum = current + n.val;
          if n.left.is_none() && n.right.is_none() {
            sum == target
          } else {
            check(&n.left, sum, target) || check(&n.right, sum, target)
          }
        }
      }
    }
    check(&root, 0, target_sum)
  }
}

const hasPathSum = (root: TreeNode | null, targetSum: number): boolean => {
  if (root === null) return false;
  const remain = targetSum - root.val;
  if (root.left === null && root.right === null) return remain === 0;
  return hasPathSum(root.left, remain) || hasPathSum(root.right, remain);
};
